import json
DATA = json.loads("""{"items": [
 {"metadata": {"namespace": "prod", "name": "api-1"}, "status": {"phase": "Running", "containerStatuses": [
   {"name": "api", "restartCount": 12, "state": {"waiting": {"reason": "CrashLoopBackOff"}}, "lastState": {"terminated": {"reason": "OOMKilled", "exitCode": 137}}}]}},
 {"metadata": {"namespace": "prod", "name": "web-1"}, "status": {"phase": "Running", "containerStatuses": [
   {"name": "web", "restartCount": 0, "state": {"running": {}}}]}},
 {"metadata": {"namespace": "dev", "name": "job-9"}, "status": {"phase": "Pending", "containerStatuses": [
   {"name": "job", "restartCount": 0, "state": {"waiting": {"reason": "ImagePullBackOff"}}}]}},
 {"metadata": {"namespace": "dev", "name": "db-0"}, "status": {"phase": "Pending"}},
 {"metadata": {"namespace": "dev", "name": "cron-3"}, "status": {"phase": "Running", "containerStatuses": [
   {"name": "c", "restartCount": 6, "state": {"running": {}}}]}}
]}""")
BAD = {"CrashLoopBackOff", "ImagePullBackOff", "ErrImagePull"}
for p in sorted(DATA["items"], key=lambda p: (p["metadata"]["namespace"], p["metadata"]["name"])):
    st = p["status"]
    why = []
    if st.get("phase") == "Pending":
        why.append("Pending")
    for c in st.get("containerStatuses", []):
        r = c.get("state", {}).get("waiting", {}).get("reason")
        if r in BAD:
            why.append(r)
        if c["restartCount"] > 5:
            last = c.get("lastState", {}).get("terminated", {}).get("reason")
            why.append(f"restarts={c['restartCount']}" + (f" last={last}" if last else ""))
    if why:
        print(f"{p['metadata']['namespace']}/{p['metadata']['name']}: {', '.join(why)}")

SUFFIX = {"Ki": 1024, "Mi": 1024**2, "Gi": 1024**3, "K": 1000, "M": 1000**2, "G": 1000**3}
def cpu(q):
    return int(q[:-1]) if q.endswith("m") else int(float(q) * 1000)  # millicores
def mem(q):
    for s, mult in SUFFIX.items():
        if q.endswith(s):
            return int(q[:-len(s)]) * mult
    return int(q)
alloc_cpu, alloc_mem = cpu("4"), mem("8Gi")
existing = [("1500m", "3Gi"), ("500m", "512Mi"), ("250m", "1Gi")]
used_cpu = sum(cpu(c) for c, _ in existing)
used_mem = sum(mem(m) for _, m in existing)
free_cpu, free_mem = alloc_cpu - used_cpu, alloc_mem - used_mem
print("free cpu (m):", free_cpu)
print("free mem (Mi):", free_mem // 1024**2)
n = min(free_cpu // cpu("500m"), free_mem // mem("1Gi"))
print("replicas that fit:", n)
print("limiting resource:", "cpu" if free_cpu // cpu("500m") < free_mem // mem("1Gi") else "memory")

import math
def bounds(replicas, surge, unavail):
    def val(v, up):
        if isinstance(v, str) and v.endswith("%"):
            x = replicas * int(v[:-1]) / 100
            return math.ceil(x) if up else math.floor(x)
        return int(v)
    s, u = val(surge, True), val(unavail, False)
    if s == 0 and u == 0:
        u = 1
    return replicas + s, replicas - u
for r, s, u in [(10, "25%", "25%"), (3, "25%", "25%"), (4, 1, 0), (1, "25%", "25%")]:
    hi, lo = bounds(r, s, u)
    print(f"replicas={r} surge={s} unavail={u} -> max pods {hi}, min available {lo}")

YAML = """apiVersion: apps/v1
kind: Deployment
spec:
  template:
    spec:
      containers:
      - name: api
        image: registry/api:latest
        resources:
          requests:
            cpu: 100m
        readinessProbe:
          httpGet: {path: /ready, port: 8000}
      - name: sidecar
        image: registry/logship:2.1
        resources:
          requests: {cpu: 50m}
          limits: {memory: 64Mi}
        livenessProbe:
          exec: {command: [true]}
        readinessProbe:
          exec: {command: [true]}
"""
blocks, cur = [], None
for line in YAML.splitlines():
    s = line.strip()
    if s.startswith("- name:"):
        cur = {"name": s.split(":", 1)[1].strip(), "text": ""}
        blocks.append(cur)
    elif cur is not None:
        cur["text"] += line + "\n"
for b in blocks:
    t, issues = b["text"], []
    image = next(l.split("image:")[1].strip() for l in t.splitlines() if "image:" in l)
    if image.endswith(":latest") or ":" not in image.split("/")[-1]:
        issues.append("image tag not pinned")
    if "requests:" not in t:
        issues.append("no requests")
    if "limits:" not in t:
        issues.append("no limits")
    if "livenessProbe:" not in t:
        issues.append("no liveness")
    if "readinessProbe:" not in t:
        issues.append("no readiness")
    print(b["name"], "->", ", ".join(issues) or "ok")

import json
from collections import Counter
EVENTS = json.loads("""[
 {"reason": "FailedScheduling", "type": "Warning", "count": 3, "involvedObject": {"name": "db-0"}, "message": "0/3 nodes are available: 3 Insufficient memory."},
 {"reason": "BackOff", "type": "Warning", "count": 40, "involvedObject": {"name": "api-1"}, "message": "Back-off restarting failed container"},
 {"reason": "Scheduled", "type": "Normal", "count": 1, "involvedObject": {"name": "web-1"}, "message": "Successfully assigned"},
 {"reason": "BackOff", "type": "Warning", "count": 12, "involvedObject": {"name": "api-2"}, "message": "Back-off restarting failed container"},
 {"reason": "FailedMount", "type": "Warning", "count": 5, "involvedObject": {"name": "db-0"}, "message": "MountVolume.SetUp failed: secret db-cred not found"}
]""")
HINT = {
 "FailedScheduling": "check requests vs node allocatable, taints, PVC binding",
 "BackOff": "kubectl logs --previous; check exit code and probes",
 "FailedMount": "missing Secret/ConfigMap/PVC or wrong namespace",
 "Unhealthy": "probe failing: check path, port and timeouts",
}
tot = Counter()
for e in EVENTS:
    if e["type"] == "Warning":
        tot[e["reason"]] += e["count"]
for reason, n in tot.most_common():
    print(f"{reason} x{n}: {HINT.get(reason, 'unknown')}")
